// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint64, uint64, uint256, bytes32, uint64, bytes32, uint256, uint256) public {
        // Do nothing before calling setL1BlockValues, just check the initial version
        string memory ver = c.version();
        assertTrue(keccak256(abi.encodePacked(ver)) == keccak256(abi.encodePacked("1.0.0")));
    }
}

